import {moveInsight,responseAdvice} from './intent.js?v=20261020-roadmap2';
import {ResearchLine} from './research.js';
import {checklist,transition,explainCandidate} from './coach.js?v=20261020-roadmap2';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tokens=s=>s.replace(/\d+\.(\.\.)?/g,'').trim().split(/\s+/).filter(Boolean);
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let saved=read('atlas-saved',[]),done=read('atlas-completed',[]),active=null,game=new Chess(),line=[],step=0,mode='line',selected=null,last=null,flipped=false,timer=null,freeStartFen=null,freePrefix=[],researchSide='w',worker=null,request=0,analysisResult=null,previewBase=null,selectedCase=null,study=null;
const names={p:'폰',n:'나이트',b:'비숍',r:'룩',q:'퀸',k:'킹'};
const sideTitle=g=>profile(g).side==='w'?'백':'흑';
const cats=[...new Set(guides.map(g=>g.category))];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600);}
function persist(){try{localStorage.setItem('atlas-saved',JSON.stringify(saved));localStorage.setItem('atlas-completed',JSON.stringify(done));}catch{toast('학습 기록을 저장할 수 없습니다.');}}
function stop(){clearInterval(timer);timer=null;}
function cancelAnalysis(){request++;worker?.terminate();worker=null;analysisResult=null;}
if(read('atlas-dark',false))document.body.classList.add('dark');
$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('atlas-dark',JSON.stringify(document.body.classList.contains('dark')))}catch{}};
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');
function matches(g,q){return [g.name,g.en,g.category,g.line].join(' ').toLowerCase().includes(q.toLowerCase());}
function sidebar(){const gs=guides.filter(g=>matches(g,$('#search').value));$('#guide-count').textContent=guides.length;$('#side-list').innerHTML=cats.filter(c=>gs.some(g=>g.category===c)).map(c=>`<div class="group-title">${esc(c)}</div>${gs.filter(g=>g.category===c).map(g=>`<a class="side-link ${active?.id===g.id?'selected':''}" href="#opening/${g.id}" ${active?.id===g.id?'aria-current="page"':''}>${esc(g.name)}<small>${done.includes(g.id)?'✓':''}</small></a>`).join('')}`).join('')||'<p class="small muted">일치하는 오프닝이 없습니다.</p>';}
$('#search').oninput=sidebar;
$('#search').onkeydown=e=>{if(e.key==='Enter'){location.hash='library';library($('#search').value);}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='/'){e.preventDefault();$('#sidebar').classList.add('open');$('#search').focus();}if(active&&['line','free'].includes(mode)&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const delta=e.key==='ArrowRight'?1:-1;if(mode==='line')go(step+delta);else seekResearch(study.cursor+delta);}});

function opening(g){stop();cancelAnalysis();active=g;line=tokens(g.line);game.reset();step=0;mode='line';selected=null;last=null;flipped=false;freeStartFen=null;freePrefix=[];previewBase=null;researchSide=profile(g).side;selectedCase=lessons[g.id].cases[0];sidebar();document.title=g.name+' ('+sideTitle(g)+') · 오프닝 아틀라스';
 $('#main').innerHTML=`<div class="crumb"><a href="#library">오프닝 도감</a><span>/</span><span>${esc(g.category)}</span></div><div class="title-row"><div><div class="eyebrow">${esc(g.en)}</div><h1>${esc(g.name)} <span class="opening-side">(${sideTitle(g)})</span></h1></div><button class="save" id="save">${saved.includes(g.id)?'★ 저장됨':'☆ 저장하기'}</button></div><p class="subtitle">${esc(lessons[g.id].summary)}</p><section id="learn"><div class="workspace"><div class="board-card"><div class="board-head"><span id="board-mode-label">수순 따라가기</span><small id="turn-label"></small></div><div class="board-frame"><div class="board" id="board" aria-label="인터랙티브 체스판"></div></div><div class="board-controls"><div class="steps"><button id="start" aria-label="처음으로">⏮</button><button id="prev" aria-label="이전 수">‹</button><button id="play" aria-label="자동 재생">▶</button><button id="next" aria-label="다음 수">›</button><button id="end" aria-label="마지막으로">⏭</button></div><button id="flip" aria-label="체스판 뒤집기">↻</button></div><div class="mode-label" id="board-caption"></div></div><div class="panel"><div class="panel-top"><span>오프닝 연구실</span><small id="line-count"></small></div><div class="tabs"><button data-mode="line" class="active">수순 보기</button><button data-mode="train">직접 두기</button><button data-mode="free">실전 대응</button></div><div class="panel-body" id="panel-body"></div></div></div></section><section id="learning"></section><div class="callout essential-caution"><strong>이것만 주의하세요</strong>${esc(g.caution)}</div><details class="compact-detail"><summary>이 오프닝의 출처별 평가</summary><div class="tier-pair"><div class="tier-box"><small>체스프릭</small><b>${esc(g.cf)}</b><a href="${sources[2].url}" target="_blank" rel="noopener">원문</a></div><div class="tier-box"><small>히카루·고담</small><b>${esc(g.hk)}</b><a href="${sources[3].url}" target="_blank" rel="noopener">원문</a></div></div></details><div class="source-inline"><a href="#sources">출처·선정 기준</a><a href="./chess-LICENSE.txt" target="_blank">chess.js 라이선스</a><a href="./engine/NOTICE.txt" target="_blank">Stockfish 출처·라이선스</a><a href="./pieces/NOTICE.txt" target="_blank">기물 이미지 출처</a></div>`;
 $('#save').onclick=()=>{saved=saved.includes(g.id)?saved.filter(id=>id!==g.id):[...saved,g.id];persist();$('#save').textContent=saved.includes(g.id)?'★ 저장됨':'☆ 저장하기';};
 $('#start').onclick=()=>mode==='free'?seekResearch(0):go(0);$('#prev').onclick=()=>mode==='free'?seekResearch(study.cursor-1):go(step-1);$('#next').onclick=()=>mode==='free'?seekResearch(study.cursor+1):go(step+1);$('#end').onclick=()=>mode==='free'?seekResearch(study.moves.length):go(line.length);$('#flip').onclick=()=>{flipped=!flipped;renderBoard();};
 $('#play').onclick=()=>{if(timer){stop();$('#play').textContent='▶';return;}if(step===line.length)go(0);timer=setInterval(()=>{if(step===line.length){stop();$('#play').textContent='▶';}else go(step+1);},950);$('#play').textContent='Ⅱ';};
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
 mountLearning(g,(pgn,label,studyCase)=>{selectedCase=studyCase;line=tokens(pgn);setMode('line');go(line.length);setMode('free');$('#board-caption').textContent=label+' · 실전 대응';$('#learn').scrollIntoView({behavior:'smooth'});});renderBoard();renderPanel();
}
function renderBoard(){if(!$('#board'))return;const files=flipped?'hgfedcba':'abcdefgh',ranks=flipped?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1],legal=selected?game.moves({square:selected,verbose:true}).map(m=>m.to):[];
 $('#board').innerHTML=ranks.flatMap((r,ri)=>[...files].map((f,fi)=>{const sq=f+r,p=game.get(sq);return `<button class="sq ${(f.charCodeAt(0)-97+r)%2===1?'dark-square':''} ${selected===sq?'chosen':''} ${legal.includes(sq)?'legal':''} ${last&&(last.from===sq||last.to===sq)?'last':''}" data-square="${sq}" aria-label="${p?(p.color==='w'?'백':'흑')+' '+names[p.type]+', ':''}${sq}">${p?`<img class="piece-img" src="./pieces/${p.color}${p.type.toUpperCase()}.svg" alt="" draggable="false">`:''}${fi===0?`<span class="coordinate">${r}</span>`:''}${ri===7?`<span class="coordinate file">${f}</span>`:''}</button>`;})).join('');
 $('#board').querySelectorAll('[data-square]').forEach(b=>b.onclick=()=>squareClick(b.dataset.square));$('#turn-label').textContent=(game.turn()==='w'?'백':'흑')+' 차례'+(game.isCheck()?' · 체크':'');$('#board-mode-label').textContent=mode==='free'?'현재 국면 · 실전 대응':mode==='train'?'대표 수순 연습':'수순 따라가기';$('#board-caption').textContent=mode==='line'?`대표 수순 · ${step} / ${line.length} 반수`:mode==='train'?`${profile(active).side==='w'?'백':'흑'}으로 연습 · ${step} / ${line.length}`:`${previewBase?'계산 수순':'실전 기록'} · ${study.cursor} / ${study.moves.length} 반수 · ← →로 이동`;
 const cursor=mode==='free'?study.cursor:step,total=mode==='free'?study.moves.length:line.length;
 ['start','prev','next','end','play'].forEach(id=>$('#'+id).disabled=mode==='train'||(id==='play'?mode!=='line':(['start','prev'].includes(id)?cursor===0:cursor===total)));
}
function go(n){if(mode!=='line')return;step=Math.max(0,Math.min(line.length,n));game.reset();last=null;for(let i=0;i<step;i++)last=game.move(line[i]);selected=null;renderBoard();renderPanel();}
function setMode(m){stop();cancelAnalysis();$('#play').textContent='▶';if(m==='free'){if(mode!=='free'){freeStartFen=game.fen();freePrefix=game.history();study=new ResearchLine(freeStartFen);game=study.game();previewBase=null;}}else{game.reset();step=0;last=null;previewBase=null;}mode=m;selected=null;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='train')autoOpponent();renderBoard();renderPanel();}
function autoOpponent(){while(step<line.length&&game.turn()!==profile(active).side){last=game.move(line[step++]);}if(step===line.length&&!done.includes(active.id)){done.push(active.id);persist();sidebar();}}
function renderPanel(){if(!$('#panel-body'))return;$('#line-count').textContent=line.length+'개 반수';const p=$('#panel-body');
 if(mode==='line'){const note=step?moveReason(line.join(' '),step):null;p.innerHTML=`<div class="move-list">${line.map((m,i)=>`${i%2===0?`<small>${i/2+1}.</small>`:''}<button data-step="${i+1}" class="${step===i+1?'current':''}" aria-label="${Math.floor(i/2)+1}수 ${i%2?'흑':'백'} ${esc(m)}">${esc(m)}</button>`).join('')}</div><div class="callout"><strong>${step?`${Math.ceil(step/2)}수 ${step%2?'백':'흑'} · ${esc(line[step-1])}`:'수순보다 목적을 먼저'}</strong>${note?`<p>${esc(note.why)}</p><details><summary>위협과 상대 대응</summary><p>${esc(note.threat)}</p><p>${esc(note.ignore)}</p></details>`:'수를 넘기면 그 수의 목적을 볼 수 있습니다.'}</div>${step===line.length?roadmapHTML(active,selectedCase,profile(active).side,true):''}<button class="primary wide" id="deviation-start">여기서 상대가 다른 수를 둔다면?</button><button class="wide" id="begin-training">이 수순 직접 연습</button>`;p.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('#deviation-start').onclick=()=>setMode('free');$('#begin-training').onclick=()=>setMode('train');
 }else if(mode==='train'){p.innerHTML=`<span class="badge">${profile(active).side==='w'?'백':'흑'}으로 연습</span><h3>${step===line.length?'수순 완성 ✓':'다음 수를 직접 두세요'}</h3><div id="feedback" class="callout" aria-live="polite">${step===line.length?'학습 기록을 저장했습니다.':'기물과 목적지 칸을 선택하세요. 상대 수는 자동으로 둡니다.'}</div><button id="hint" ${step===line.length?'disabled':''}>힌트</button> <button id="reset-training">다시 연습</button><div id="hint-text" class="small muted"></div><button id="train-free" class="primary wide">다른 합법 수와 비교</button>`;$('#hint').onclick=()=>$('#hint-text').textContent=line[step]+' · '+moveReason(line.join(' '),step+1).why;$('#reset-training').onclick=()=>setMode('train');$('#train-free').onclick=()=>setMode('free');
 }else renderResearch();
}
function seekResearch(at){cancelAnalysis();game=study.seek(at);last=game.history({verbose:true}).at(-1)||null;selected=null;renderBoard();renderPanel();}
function applyFree(san){try{game=study.append(san);previewBase=null;last=game.history({verbose:true}).at(-1);selected=null;cancelAnalysis();renderBoard();renderPanel();}catch{toast('현재 국면에서 둘 수 없는 수입니다.');}}
function squareClick(sq){if(mode==='line'){toast('실전 대응 또는 직접 두기를 선택하세요.');return;}if(game.isGameOver()){toast('종료된 국면입니다. 되돌리거나 다시 시작하세요.');return;}if(mode==='train'&&step===line.length)return;const piece=game.get(sq);if(!selected||piece?.color===game.turn()){selected=piece?.color===game.turn()?sq:null;renderBoard();return;}const from=selected;selected=null;let move;try{move=new Chess(game.fen()).move({from,to:sq,promotion:'q'});}catch{toast('그 칸으로 이동할 수 없습니다.');renderBoard();return;}if(mode==='train'){const expected=new Chess(game.fen()).move(line[step]);if(move.from!==expected.from||move.to!==expected.to){$('#feedback').innerHTML='<strong>다른 합법 수입니다.</strong>지정 수순 연습입니다. 실전 대응에서 이 수의 후속 응수를 계산해 보세요.';renderBoard();return;}last=game.move({from,to:sq,promotion:'q'});step++;autoOpponent();renderBoard();renderPanel();}else applyFree(move.san);}
function researchPosition(){const c=new Chess();try{for(const m of [...freePrefix,...game.history()])c.move(m);return c.fen()===game.fen()?c:game;}catch{return game;}}
function renderResearch(){const history=[...freePrefix,...game.history()],tr=transition(history,active,line),checks=checklist(game,active,researchSide),legal=game.isGameOver()?[]:game.moves(),who=game.turn()===researchSide?'내':'상대',current=researchPosition(),advice=responseAdvice(current,active,researchSide,selectedCase),shown=moveInsight(current.history({verbose:true}).at(-1),active,researchSide,selectedCase),choice=choosePlan(current,active,researchSide,selectedCase,line);
 $('#panel-body').innerHTML=`<div class="research-heading"><h3>상대가 다르게 둔다면?</h3><label>내 진영 <select id="research-side" aria-label="연구할 진영"><option value="w" ${researchSide==='w'?'selected':''}>백</option><option value="b" ${researchSide==='b'?'selected':''}>흑</option></select></label></div><div class="deviation-status"><b>${esc(tr.title)}</b><p>${esc(tr.detail)}</p>${tr.link?`<a href="#opening/${tr.link}">이 갈래의 핵심 계획 보기 ↗</a>`:''}</div><div class="research-input"><label for="alternative-move">현재 ${who} 차례 · 다른 수 선택</label><div><select id="alternative-move" ${!legal.length?'disabled':''}><option value="">합법 수 ${legal.length}개 중 선택</option>${legal.map(m=>`<option>${esc(m)}</option>`).join('')}</select><button id="apply-alternative" ${!legal.length?'disabled':''}>두기</button></div></div><section class="research-timeline" aria-label="실전 수순 탐색"><div class="research-navigation"><button id="free-undo" aria-label="실전 이전 수" ${study.cursor===0?'disabled':''}>‹ 이전 수</button><span aria-live="polite">${previewBase?'계산 수순':'실전 기록'} ${study.cursor} / ${study.moves.length}</span><button id="free-redo" aria-label="실전 다음 수" ${study.cursor===study.moves.length?'disabled':''}>다음 수 ›</button></div><div class="history-moves"><button data-history="0" ${study.cursor===0?'aria-current="step"':''}>시작</button>${study.moves.map((m,i)=>`<button data-history="${i+1}" ${study.cursor===i+1?'aria-current="step"':''}>${Math.floor((freePrefix.length+i)/2)+1}${(freePrefix.length+i)%2?'…':'.'} ${esc(m)}</button>`).join('')}</div><p class="small muted">이전·다음과 보드 아래 화살표로 한 수씩 이동합니다. 돌아간 곳에서 새 수를 두면 이후 기록이 새 갈래로 바뀝니다.</p></section>${shown?`<section class="move-insight" aria-label="현재 수의 의도"><div class="insight-heading"><b>${esc(shown.title)}</b><span>${shown.own?'내 수':'상대 수'} · ${previewBase?'계산 수순':'현재 기록'}</span></div><p><strong>왜 두나요?</strong> ${esc(shown.why)}</p>${shown.pressure?`<p>${esc(shown.pressure)}</p>`:''}<div class="intent-tag ${shown.kind}">${esc(shown.relation)}</div><p><strong>이후에는</strong> ${esc(shown.next)}</p><details><summary>해설의 기준</summary><p>${esc(shown.note)}</p><p>선택한 대표 구조에서 ${shown.own?'내':'상대'} 목표: ${esc(shown.goal)}. 실제 교환과 말 배치에 따라 달라집니다.</p></details></section>`:''}<section class="decision-card choice-${choice.selected}" aria-label="지금 선택할 계획"><small>상대 수: ${esc(advice.opponent)}</small><div class="choice-options">${[['continue','그대로 진행'],['respond','먼저 대응'],['switch','새 계획']].map(([id,t])=>`<span class="${choice.selected===id?'chosen-choice':''}">${choice.selected===id?'✓ ':''}${t}</span>`).join('')}</div><h3>${esc(choice.verdict)}</h3><p>${esc(choice.because)}</p><div class="choice-first"><b>지금 먼저 할 일</b><p>${esc(choice.first)}</p>${choice.example?`<p class="move-example">대표 수순의 다음 수: <b>${esc(choice.example)}</b> (${game.turn()===researchSide?'내':'상대'} 차례)</p>`:''}</div><b>${choice.preparing?'배치를 마친 뒤 이어갈 계획':'이어갈 계획'} · ${esc(choice.planName)}</b><ol class="essential-plan">${choice.route.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><details><summary>목표와 판단 근거</summary><p><b>목표</b> ${esc(choice.route.goal)}</p><p>${esc(choice.note)}</p><p><b>상대 수의 효과</b> ${esc(advice.reason)}</p></details></section><details class="position-checks"><summary>지금 할 일</summary>${checks.map(x=>`<div class="check-item ${x.focus?'focused':''}"><b>${x.focus?'● ':''}${esc(x.title)}</b><p>${esc(x.text)}</p></div>`).join('')}</details><button id="calculate" class="primary wide" ${game.isGameOver()?'disabled':''}>${who} 수와 후속 응수 계산</button><div id="analysis-output" aria-live="polite">${game.isGameOver()?`<div class="callout"><strong>${game.isCheckmate()?'체크메이트':game.isStalemate()?'스테일메이트':'무승부'}</strong>종료된 국면입니다.</div>`:'<p class="small muted">현재 차례의 후보 3개와 상대 응수를 비교합니다. 보드에서 원하는 다른 수를 둔 뒤 다시 계산할 수 있습니다.</p>'}</div><div class="research-actions"><button id="free-reset">연구 시작 국면</button>${previewBase?'<button id="preview-back">후보 비교 국면으로</button>':''}</div><details class="compact-detail"><summary>현재 기보 · 계산 범위</summary><p class="line-text">${esc(history.join(' ')||'시작 국면')}</p><p class="small muted">Stockfish 19 lite가 브라우저 안에서 약 2초 동안 후보 세 개를 계산합니다. 엔진 탐색 깊이를 표시하고, 후속 수순은 최대 8반수까지 제공합니다. 짧은 계산이므로 장기 전략이나 모든 전술을 보장하지 않습니다.</p><a href="https://lichess.org/analysis/standard/${game.fen().replace(/ /g,'_')}" target="_blank" rel="noopener">더 깊게 분석하기 ↗</a></details>`;
 $('#research-side').onchange=e=>{cancelAnalysis();researchSide=e.target.value;renderResearch();};$('#apply-alternative').onclick=()=>{const san=$('#alternative-move').value;if(san)applyFree(san);else toast('둘 수를 선택하세요.');};$('#calculate').onclick=calculate;
 $('#free-undo').onclick=()=>seekResearch(study.cursor-1);$('#free-redo').onclick=()=>seekResearch(study.cursor+1);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>seekResearch(+b.dataset.history));
 $('#free-reset').onclick=()=>seekResearch(0);if($('#preview-back'))$('#preview-back').onclick=()=>{const base=previewBase;cancelAnalysis();game=study.restore(base.snapshot);previewBase=null;analysisResult=base.result;last=game.history({verbose:true}).at(-1)||null;selected=null;renderBoard();renderPanel();};
 if(previewBase)showAnalysis(previewBase.result);else if(analysisResult?.fen===game.fen())showAnalysis(analysisResult);
}
function calculate(){previewBase=null;cancelAnalysis();renderBoard();renderResearch();const id=request,fen=game.fen(),b=$('#calculate');b.disabled=true;b.textContent='합법 수와 후속 응수를 계산 중…';$('#analysis-output').innerHTML='<p role="status">계산 중입니다. 다른 국면으로 이동하면 이 계산은 취소됩니다.</p>';try{worker=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.id!==request||mode!=='free'||game.fen()!==data.fen)return;worker?.terminate();worker=null;b.disabled=false;b.textContent='다시 계산';if(data.error){$('#analysis-output').textContent=data.error;return;}analysisResult=data;showAnalysis(data);};worker.onerror=()=>{worker?.terminate();worker=null;if(id!==request)return;b.disabled=false;b.textContent='다시 계산';$('#analysis-output').textContent='계산을 시작하지 못했습니다. 새로고침하거나 외부 분석판을 이용하세요.';};worker.postMessage({id,fen,history:[...freePrefix,...game.history()]});}catch{b.disabled=false;b.textContent='다시 계산';$('#analysis-output').textContent='이 브라우저에서 계산 기능을 사용할 수 없습니다.';}}
function showAnalysis(result){const root=$('#analysis-output');if(!root||(result.fen!==game.fen()&&previewBase?.result!==result))return;root.innerHTML=`<div class="analysis-meta">${previewBase?`후보 ${previewBase.index+1} 재생 중 · 계산 기준 국면의 결과<br>`:""}${esc(result.engine||'Stockfish')} · 탐색 깊이 ${result.depth} · ${result.nodes.toLocaleString()}노드</div>${!result.candidates.length?(result.terminal?'<p>종료된 국면입니다. 더 둘 수 없습니다.</p>':'<p>이 시간 안에 비교 가능한 후보를 완성하지 못했습니다. 다시 계산해 보세요.</p>'):result.candidates.map((x,i)=>{const e=explainCandidate(result.fen,x.san,active,researchSide);return `<div class="candidate"><div><b>후보 ${i+1} · ${esc(x.san)}</b><button data-pv="${i}">수순 확인</button></div><p>${esc(e.text)}</p><small>${esc(e.relation)}</small><div class="pv">${x.pv.map((m,j)=>`<button data-candidate="${i}" data-ply="${j+1}" aria-label="후보 ${i+1} ${j+1}반수까지 보기">${j+1}. ${esc(m)}</button>`).join('<span> → </span>')}</div></div>`;}).join('')}<p class="small muted">제한된 시간의 후보입니다. 상대도 다른 수를 선택할 수 있습니다. 수순 확인을 누르면 첫 수부터 시작합니다. 이전·다음 버튼으로 최대 8반수를 한 수씩 확인하세요.</p>`;
 const play=(i,n)=>{const snapshot=previewBase?.result===result?previewBase.snapshot:study.snapshot();cancelAnalysis();study.restore(snapshot);previewBase={snapshot,result,index:i};game=study.variation(result.candidates[i].pv,n);last=game.history({verbose:true}).at(-1)||null;selected=null;renderBoard();renderPanel();};root.querySelectorAll('[data-pv]').forEach(b=>b.onclick=()=>play(+b.dataset.pv,1));root.querySelectorAll('[data-ply]').forEach(b=>b.onclick=()=>play(+b.dataset.candidate,+b.dataset.ply));}

function library(initial=''){document.title='오프닝 도감 · 오프닝 아틀라스';$('#main').innerHTML=`<div class="eyebrow">A SMALLER REPERTOIRE</div><h1>핵심 오프닝 ${guides.length}개</h1><p class="subtitle">목적을 이해하고, 다른 수에도 계획을 이어가는 연습.</p><details class="compact-detail"><summary>어떤 오프닝을 남겼나요?</summary><p>${ratingPolicy}</p><p class="small muted">${removed.length}개 가이드를 제외했습니다. 평가가 엇갈린 오프닝은 유지하며, 세부 수순 전체 목록은 제공하지 않습니다.</p></details><div class="filter-row"><input id="filter-query" aria-label="도감 검색" placeholder="이름 또는 수순 검색" value="${esc(initial)}"><select id="filter-category" aria-label="상황 선택"><option value="">모든 상황</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="cards" id="library-results"></div>`;function draw(){const gs=guides.filter(g=>matches(g,$('#filter-query').value)&&(!$('#filter-category').value||g.category===$('#filter-category').value));$('#library-results').innerHTML=gs.map(g=>`<a class="card" href="#opening/${g.id}"><span class="badge neutral">${esc(g.category)}</span><h3>${esc(g.name)} <span class="opening-side">(${sideTitle(g)})</span></h3><p>${esc(lessons[g.id].summary)}</p><footer>${esc(g.level)} · ${done.includes(g.id)?'✓ 연습 완료':esc(g.style)}</footer></a>`).join('')||'<div class="empty">일치하는 오프닝이 없습니다.</div>';}$('#filter-query').oninput=draw;$('#filter-category').onchange=draw;draw();}
function compare(){document.title='출처별 평가 · 오프닝 아틀라스';$('#main').innerHTML=`<h1>출처별 평가</h1><p class="subtitle">학습 목록에 남긴 ${guides.length}개만 비교합니다.</p><details class="compact-detail"><summary>선정 기준과 척도 차이</summary><p>${ratingPolicy}</p><p>히카루·고담의 상위 세 구간은 유지, Really, Bro·Tricks Only·Garbage는 제외 구간으로 사용합니다. 객관적 강함의 순위가 아닙니다.</p></details><div class="table-wrap"><table><thead><tr><th>오프닝</th><th>체스프릭</th><th>히카루·고담</th></tr></thead><tbody>${guides.map(g=>`<tr><td><a href="#opening/${g.id}">${esc(g.name)}</a><small class="muted"> · ${esc(g.category)}</small></td><td>${esc(g.cf)}</td><td>${esc(g.hk)}</td></tr>`).join('')}</tbody></table></div>`;}
function principles(){$('#main').innerHTML=`<h1>다른 수를 만났을 때</h1><p class="subtitle">수순을 외워서 이어 두기 전에 네 가지를 확인하세요.</p>${[['위협부터','체크·잡기·강한 위협이 있으면 먼저 처리합니다.'],['중앙 구조','중앙이 열렸는지 닫혔는지, 어느 폰 브레이크가 가능한지 확인합니다.'],['전개와 킹','덜 활동적인 말을 개선하고, 중앙을 열기 전 내 킹을 점검합니다.'],['후보 비교','실전 대응에서 상대 수를 선택하고, 내 후보와 후속 응수를 계산합니다.']].map(([t,s],i)=>`<div class="principle"><div class="num">0${i+1}</div><div><h2>${t}</h2><p>${s}</p></div></div>`).join('')}<a href="#opening/italian" class="primary">이탈리안에서 연습 →</a>`;}
function savedPage(){const gs=guides.filter(g=>saved.includes(g.id));$('#main').innerHTML=`<h1>저장한 오프닝</h1><p class="small muted">현재 학습 목록의 저장 항목입니다. 이 브라우저에 보관됩니다.</p><div class="cards">${gs.map(g=>`<a class="card" href="#opening/${g.id}"><h3>${esc(g.name)} <span class="opening-side">(${sideTitle(g)})</span></h3><p>${esc(lessons[g.id].summary)}</p></a>`).join('')}</div>${!gs.length?'<p class="empty">저장한 오프닝이 없습니다.</p>':''}`;}
function route(){const hash=decodeURIComponent(location.hash.slice(1)||'opening/vienna');stop();cancelAnalysis();active=null;$('#sidebar').classList.remove('open');if(hash.startsWith('opening/')){const g=guides.find(g=>g.id===hash.slice(8));if(g)opening(g);else{library();toast('선정 기준에서 제외된 오프닝입니다. 남긴 목록을 확인하세요.');}}else if(hash==='strategy-compare'){strategyCompare();document.title='전략 비교 · 오프닝 아틀라스';}else if(hash==='compare')compare();else if(hash==='sources'){$('#main').innerHTML=sourceNotes(sources);}else if(hash==='saved')savedPage();else if(hash==='principles')principles();else library();mountPurpose(active);sidebar();document.querySelectorAll('header nav a').forEach(a=>a.classList.toggle('active',a.hash===location.hash||(a.hash==='#library'&&active)));window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
